async page => {
  const out = 'C:/Users/sj930/Documents/Codex/2026-10-22/kfcoding-aihub-ooioo-fluxionai-users-shenjian/outputs/playwright/v022/';
  const errors = [], blocked = [], results = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.unroute('**/*');
  await page.route('**/*', route => {
    const u = new URL(route.request().url());
    if (u.hostname === '127.0.0.1' && u.port === '8767') return route.continue();
    blocked.push(u.origin + u.pathname); return route.abort('blockedbyclient');
  });
  const ref = name => page.locator('[data-ref="' + name + '"]');
  const check = (condition, text) => { if (!condition) throw Error(text); };
  const evidence = () => page.evaluate(() => structuredClone(window.localEvidence));
  const counters = async () => { const e = await evidence(); return [e.requests.length,e.configWrites,e.modelCalls,e.groupWrites.length]; };
  const assertSame = async (before, message) => check(JSON.stringify(await counters()) === JSON.stringify(before), message);
  const focus = async name => ref(name).evaluate(e => e.getRootNode().activeElement === e);
  const routeSettings = async () => { await page.locator('#kf-tab-settings').click(); await page.locator('[data-settings-target=routing]').click(); };
  for (const width of [1360,390,320]) {
    for (const theme of ['dark','light']) {
      await page.setViewportSize({width,height:1000});
      await page.emulateMedia({colorScheme:theme,reducedMotion:width===320?'reduce':'no-preference'});
      await page.goto('http://127.0.0.1:8767/v022.html?site=aihub&pelican&theme='+theme);
      await ref('check').click();
      await ref('candidateRows').locator('.candidate').first().waitFor();
      await routeSettings();
      check(await ref('automaticSwitchMode').inputValue()==='failover','mode restored');
      await ref('automaticSwitchMode').selectOption('strategy');
      check((await ref('automaticSwitchHint').innerText()).includes('择优'),'strategy hint');
      await ref('automaticSwitchMode').selectOption('failover');
      check((await ref('automaticSwitchHint').innerText()).includes('不自动切回'),'failover hint');
      await ref('tokenSelectToggle').click();
      check(await focus('tokenSearch'),'token search focus');
      let before=await counters();
      await ref('tokenSearch').fill('Kimi');
      check(await ref('tokenList').locator('.token-option:not([hidden])').count()===39,'key group search');
      check(await ref('tokenList').locator('input[data-token-id="1"]').isChecked(),'hidden key retained');
      check((await ref('tokenCount').innerText())==='已选 1/40','full key count');
      await ref('tokenSearch').press('ArrowDown');
      check(await ref('tokenList').locator('input[data-token-id="2"]').evaluate(e=>e.getRootNode().activeElement===e),'ArrowDown focuses visible option');
      await ref('tokenSearch').fill('不存在');
      check((await ref('tokenSearchStatus').innerText()).includes('无匹配'),'key no results');
      await ref('tokenSearch').press('Escape');
      check(await ref('tokenSearch').inputValue()==='','Escape clears query');
      await ref('tokenSearch').press('Escape');
      check(await ref('tokenMenu').isHidden(),'second Escape closes');
      check(await focus('tokenSelectToggle'),'Escape restores trigger focus');
      await assertSame(before,'key search saves or requests');
      await ref('modelSelectToggle').click();
      before=await counters();
      await ref('modelSearch').fill('kimi');
      check(await ref('modelList').locator('.token-option:not([hidden])').count()===1,'model platform search');
      check(await ref('modelList').locator('input[data-model-name="gpt-6.1-sol"]').isChecked(),'hidden model retained');
      await ref('modelSearch').fill('不存在');
      check((await ref('modelSearchStatus').innerText()).includes('无匹配'),'model no results');
      await ref('modelSearch').press('Escape');await ref('modelSearch').press('Escape');
      await assertSame(before,'model search saves or requests');
      await ref('groupFilterSelectToggle').click();
      before=await counters();
      await ref('groupFilterSearch').fill('Kimi-40');
      check(await ref('groupFilterList').locator('.token-option:not([hidden])').count()===1,'group search');
      await assertSame(before,'group search saves or requests');
      await ref('groupFilterList').locator('input[data-group-name="Kimi-40"]').check();
      await ref('groupFilterSearch').fill('OpenAI');
      check(await ref('groupFilterList').locator('input[data-group-name="Kimi-40"]').isChecked(),'hidden group retained');
      await ref('clearGroupFilter').click();
      check(await ref('groupFilterList').locator('input:checked').count()===0,'clear all includes hidden selection');
      await ref('groupFilterSearch').press('Escape');await ref('groupFilterSearch').press('Escape');
      await page.locator('[data-settings-target=quality]').click();
      before=await counters();
      await ref('imageQualityKeySearch').fill('模拟密钥-40');
      check(await ref('imageQualityKey').inputValue()==='1','scoring key retained');
      check(await ref('imageQualityKey').locator('option').count()===3,'scoring key filtered plus neutral/current');
      await ref('imageQualityKeySearch').fill('不存在');
      check((await ref('imageQualityKeySearchStatus').innerText()).includes('无匹配'),'scorer no results');
      await ref('imageQualityKeySearch').press('Escape');
      await page.locator('details').filter({has:ref('imageQualityFallback1Search')}).locator('summary').click();
      for (const n of [1,2]) {
        await ref('imageQualityFallback'+n+'Search').fill('Kimi-40');
        check(await ref('imageQualityFallback'+n).inputValue()===String(n+1),'fallback retains current');
        check(await ref('imageQualityFallback'+n).locator('option').count()===3,'fallback filtered plus neutral/current');
        await ref('imageQualityFallback'+n+'Search').fill('不存在');
        check((await ref('imageQualityFallback'+n+'SearchStatus').innerText()).includes('无匹配'),'fallback no results');
        await ref('imageQualityFallback'+n+'Search').press('Escape');
      }
      await assertSame(before,'quality search saves, requests or changes groups');
      await page.locator('#kf-tab-monitor').click();
      await ref('manualSwitch').click();
      check(await focus('manualGroupSearch'),'manual search focus');
      before=await counters();
      await ref('manualGroupSearch').fill('Kimi-40');
      await ref('manualGroup').locator('input[data-manual-group="Kimi-40"]').check();
      await ref('manualGroupSearch').fill('OpenAI');
      check(await ref('manualGroup').locator('input[data-manual-group="Kimi-40"]').isChecked(),'manual hidden selection retained');
      check(await ref('manualConfirm').isEnabled(),'manual hidden selection remains confirmable');
      await ref('manualGroupSearch').fill('不存在');
      check((await ref('manualGroupSearchStatus').innerText()).includes('无匹配'),'manual no results');
      await ref('manualGroupSearch').press('Escape');
      await assertSame(before,'manual search saves or requests');
      await ref('manualClose').click();
      await routeSettings();
      await ref('tokenSelectToggle').click();
      await ref('tokenSearch').fill('不存在');
      await ref('selectAllTokens').click();
      check(await ref('tokenList').locator('input:checked').count()===40,'select all includes hidden choices');
      await ref('clearTokens').click();
      check(await ref('tokenList').locator('input:checked').count()===0,'clear all includes hidden choices');
      await ref('tokenSearch').press('Escape');
      await ref('tokenList').locator('input[data-token-id="1"]').check();
      await ref('tokenSearch').press('Escape');
      const layout=await ref('automaticSwitchMode').evaluate(e=>{
        const p=e.closest('.panel'), bar=e.closest('.automation-bar');
        const boxes=[...bar.children].map(n=>n.getBoundingClientRect());
        return {panel:p.clientWidth,panelScroll:p.scrollWidth,bar:bar.clientWidth,barScroll:bar.scrollWidth,
          controlsInside:boxes.every(b=>b.left>=bar.getBoundingClientRect().left-1&&b.right<=bar.getBoundingClientRect().right+1),
          theme:e.getRootNode().host.dataset.resolvedTheme,reduced:matchMedia('(prefers-reduced-motion:reduce)').matches};
      });
      check(layout.panelScroll<=layout.panel+1&&layout.barScroll<=layout.bar+1&&layout.controlsInside,'routing layout overflow');
      check(layout.theme===theme,'theme mismatch');
      await ref('automaticSwitchMode').scrollIntoViewIfNeeded();
      await page.screenshot({path:out+width+'-'+theme+'-routing.png'});
      await page.locator('#kf-tab-monitor').click();
      await page.evaluate(()=>{localEvidence.slowMonitor=true;});
      await ref('check').click();
      const motion=await ref('status').evaluate(e=>({tone:e.dataset.tone,animation:getComputedStyle(e,'::before').animationName}));
      check(motion.tone==='running','running status not exercised');
      check(motion.animation===(width===320?'none':'status-breathe'),'status does not respect motion preference');
      await ref('statusDot').evaluate(e=>new Promise(resolve=>{const done=()=>e.dataset.tone!=='running'?resolve():setTimeout(done,10);done();}));
      await page.evaluate(()=>{localEvidence.slowMonitor=false;});
      const e=await evidence();check(e.modelCalls===0&&e.groupWrites.length===0,'configuration caused inference/write');
      results.push({width,theme,layout,motion,configWrites:e.configWrites,modelCalls:e.modelCalls,groupWrites:e.groupWrites.length});
    }
  }
  // Exercise actual timer-driven checks and runtime writes against the in-memory fixture.
  await page.goto('http://127.0.0.1:8767/v022.html?site=aihub&pelican');
  await ref('check').click();await ref('candidateRows').locator('.candidate').first().waitFor();
  await routeSettings();
  await page.clock.install();
  await ref('enabled').check();await page.clock.fastForward(1000);
  check((await evidence()).groupWrites.length===0,'healthy initial cycle switched');
  await page.evaluate(()=>{localEvidence.unknown=true;});await page.clock.fastForward(16000);
  check((await evidence()).groupWrites.length===0,'unknown state switched');
  await page.evaluate(()=>{localEvidence.unknown=false;localEvidence.fault=true;});await page.clock.fastForward(16000);
  await page.waitForFunction(()=>localEvidence.current===2);
  check((await evidence()).groupWrites.length===1,'fault did not switch once');
  await page.evaluate(()=>{localEvidence.fault=false;});await page.clock.fastForward(16000);
  const after=await evidence();check(after.current===2&&after.groupWrites.length===1,'recovered original caused failback');
  check(after.modelCalls===0,'failover requested model');
  await ref('enabled').uncheck();
  await page.clock.resume();
  await page.evaluate(()=>{localEvidence.failKeys=true;});
  await page.locator('#kf-tab-monitor').click();await ref('check').click();
  await ref('status').filter({hasText:'处理失败'}).waitFor();
  await page.screenshot({path:out+'error-state.png'});
  results.push({runtime:{unknownHeld:true,healthyHeld:true,recovery:after.groupWrites,noFailback:after.current===2,modelCalls:after.modelCalls},errorState:await ref('status').innerText()});
  check(errors.length===0,'browser errors: '+errors.join(';'));
  check(blocked.length===0,'external attempt: '+blocked.join(';'));
  const report={environment:'Independent Playwright browser with loopback preview and simulated endpoints; virtual clock for scheduler',realPaidCalls:0,realGroupWrites:0,externalNetworkSent:0,errors,blocked,results};
  return report;
}
